        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .none
        
        case 2: return .pointASet(aMs: try FfiConverterInt64.read(from: &buf)
        )
        
        case 3: return .active(aMs: try FfiConverterInt64.read(from: &buf), bMs: try FfiConverterInt64.read(from: &buf)
        )
        
