        case let .pointASet(aMs):
            writeInt(&buf, Int32(2))
            FfiConverterInt64.write(aMs, into: &buf)
            
        
        case let .active(aMs,bMs):
            writeInt(&buf, Int32(3))
            FfiConverterInt64.write(aMs, into: &buf)
            FfiConverterInt64.write(bMs, into: &buf)
            
        }
    }
}


